import hashlib
import unittest

from audit.hashchain import AuditLog, chain_hash


class AuditLogTest(unittest.TestCase):
    def test_new_log_is_empty(self):
        self.assertEqual(len(AuditLog()), 0)

    def test_append_rejects_blank_actor(self):
        with self.assertRaises(ValueError):
            AuditLog().append(actor="", action="login")

    def test_chain_hash_links_records(self):
        records = [b"login:ana", b"export:ana", b"logout:ana"]
        digest = b""
        for record in records:
            digest = hashlib.blake2b(digest + record, digest_size=16).digest()
        self.assertEqual(chain_hash(records), digest.hex())

    def test_records_keep_order(self):
        log = AuditLog()
        log.append(actor="ana", action="a")
        log.append(actor="ana", action="b")
        self.assertEqual([r.action for r in log], ["a", "b"])

