import unittest
from decimal import Decimal, getcontext

from savings.compound import yearly_balances


class FloatVsDecimalTest(unittest.TestCase):
    def test_float_path_within_a_cent_of_decimal_oracle(self):
        getcontext().prec = 40
        principal, rate, n, years = Decimal("125000"), Decimal("0.0435"), 12, 25
        oracle = [
            principal * (1 + rate / n) ** (n * y)
            for y in range(1, years + 1)
        ]
        got = yearly_balances(125000, 0.0435, 12, 25)
        for fast, exact in zip(got, oracle):
            self.assertLess(abs(Decimal(str(fast)) - exact), Decimal("0.01"))

