import unittest

from hypothesis import given, strategies as st

from scheduler.slots import merge_busy


intervals = st.lists(st.tuples(st.integers(0, 1440), st.integers(1, 120)).map(lambda t: (t[0], t[0] + t[1])))


class MergeBusyPropertiesTest(unittest.TestCase):
    @given(intervals)
    def test_merged_intervals_are_sorted_and_disjoint(self, busy):
        merged = merge_busy(busy)
        for (a_start, a_end), (b_start, _) in zip(merged, merged[1:]):
            self.assertLess(a_end, b_start)
            self.assertLessEqual(a_start, a_end)
        self.assertLessEqual(len(merged), len(busy))

